sourcesContent:
@tailwind base;
@tailwind components;
@tailwind utilities;

/* GitHub风格深色主题 */
:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #21262d;
  --border-color: #30363d;
  --text-primary: #f0f6fc;
  --text-secondary: #8b949e;
  --accent-blue: #58a6ff;
  --accent-green: #3fb950;
  --accent-purple: #a5a5ff;
  --accent-orange: #ffa657;
}

/* 基础样式 */
body {
  @apply bg-gray-900 text-gray-100;
  background: var(--bg-primary);
  color: var(--text-primary);
}

/* 磨砂玻璃效果 */
.glass-card {
  background: rgba(33, 38, 45, 0.8);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(48, 54, 61, 0.3);
  box-shadow: 
    0 8px 32px rgba(0, 0, 0, 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);
}

.glass-sidebar {
  background: rgba(13, 17, 23, 0.95);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-right: 1px solid rgba(48, 54, 61, 0.3);
}

.glass-header {
  background: rgba(22, 27, 34, 0.9);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid rgba(48, 54, 61, 0.3);
}

/* 自定义样式 */
.sidebar-transition {
  transition: all 0.3s ease-in-out;
}

.card-hover {
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.card-hover:hover {
  transform: translateY(-4px) scale(1.02);
  box-shadow: 
    0 20px 40px rgba(0, 0, 0, 0.4),
    0 0 0 1px rgba(255, 255, 255, 0.1);
}

/* 统计卡片特殊效果 */
.stat-card {
  @apply glass-card card-hover;
}

.stat-card-blue {
  @apply glass-card card-hover;
}

.stat-card-green {
  @apply glass-card card-hover;
}

.stat-card-orange {
  @apply glass-card card-hover;
}

.stat-card-purple {
  @apply glass-card card-hover;
}

/* 按钮样式 */
.btn-glass {
  @apply glass-card;
  transition: all 0.3s ease;
}

.btn-glass:hover {
  background: rgba(88, 166, 255, 0.1);
  border-color: var(--accent-blue);
}

/* 深色主题滚动条 */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: var(--bg-secondary);
}

::-webkit-scrollbar-thumb {
  background: var(--border-color);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: #484f58;
}

/* 导航链接样式 */
.nav-link {
  @apply transition-all duration-200;
  border-radius: 8px;
}

.nav-link:hover {
  background: rgba(88, 166, 255, 0.1);
  color: var(--accent-blue);
}

.nav-link.active {
  background: rgba(88, 166, 255, 0.15);
  color: var(--accent-blue);
}

/* 新的分组导航样式 */
.nav-group-title {
  @apply transition-all duration-200;
  border-radius: 6px;
}

.nav-group-title:hover {
  background: rgba(255, 255, 255, 0.05);
}

.nav-item {
  @apply transition-all duration-200;
  position: relative;
  border-radius: 6px;
}

.nav-item:hover {
  background: rgba(255, 255, 255, 0.08) !important;
  transform: translateX(2px);
}

.nav-item.router-link-active {
  background: rgba(16, 185, 129, 0.1) !important;
  color: #10b981 !important;
  border-left: 2px solid #10b981;
}

.nav-item.router-link-active::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 2px;
  background: linear-gradient(to bottom, #10b981, #059669);
  border-radius: 0 2px 2px 0;
}

/* 折叠动画 */
.nav-collapse-enter-active,
.nav-collapse-leave-active {
  transition: all 0.3s ease;
  overflow: hidden;
}

.nav-collapse-enter-from,
.nav-collapse-leave-to {
  opacity: 0;
  max-height: 0;
  transform: translateY(-10px);
}

.nav-collapse-enter-to,
.nav-collapse-leave-from {
  opacity: 1;
  max-height: 200px;
  transform: translateY(0);
}

/* 输入框样式 */
.input-glass {
  @apply glass-card;
  background: rgba(33, 38, 45, 0.6);
  color: var(--text-primary);
}

.input-glass:focus {
  border-color: var(--accent-blue);
  box-shadow: 0 0 0 3px rgba(88, 166, 255, 0.1);
}

/* 动画效果 */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.fade-in-up {
  animation: fadeInUp 0.6s ease-out;
}

/* 响应式调整 */
@media (max-width: 768px) {
  .glass-card {
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
  }
}
